   "motivo": "Deixa claro que A é a área lateral, sem parênteses dentro do símbolo."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["V", "volume do cilindro: o espaço que ele ocupa"],
    ["A", "área lateral: só a parede curva, sem o topo nem a base"],
    ["r", "raio: distância do centro da base até a borda"],
    ["h", "altura do cilindro"],
    ["π", "número pi, cerca de 3,14. Aparece em todas as contas e se cancela na comparação"],
    ["C, C₁, C₂", "os três cilindros do enunciado"],
    ["V₁, V₂, A₁, A₂", "volume e área lateral de C₁ e de C₂"]
   ],
   "motivo": "Faltavam π e os símbolos com índice, usados na resolução."
  },
  {
   "campo": "resolucao.passos[3].porque",
